CREATE DATABASE IF NOT EXISTS dental_clinic CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dental_clinic;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(150) NOT NULL,role ENUM('PATIENT','DOCTOR','RECEPTIONIST','ADMIN') NOT NULL,phone VARCHAR(25),active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS doctors(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,specialty VARCHAR(150) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS services(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,price INT UNSIGNED NOT NULL,duration_minutes INT NOT NULL,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS schedules(id INT AUTO_INCREMENT PRIMARY KEY,doctor_id INT NOT NULL,work_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,UNIQUE(doctor_id,work_date),FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE IF NOT EXISTS appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,service_id INT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status ENUM('PENDING','CONFIRMED','CHECKED_IN','IN_PROGRESS','COMPLETED','CANCELLED','NO_SHOW') DEFAULT 'PENDING',reason TEXT,FOREIGN KEY(patient_id) REFERENCES users(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(service_id) REFERENCES services(id),INDEX(doctor_id,starts_at));
CREATE TABLE IF NOT EXISTS records(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNIQUE NOT NULL,diagnosis TEXT NOT NULL,plan TEXT NOT NULL,notes TEXT,follow_up DATE,FOREIGN KEY(appointment_id) REFERENCES appointments(id));
CREATE TABLE IF NOT EXISTS treatments(id INT AUTO_INCREMENT PRIMARY KEY,record_id INT NOT NULL,description TEXT NOT NULL,status ENUM('PLANNED','DONE') DEFAULT 'PLANNED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(record_id) REFERENCES records(id));
CREATE TABLE IF NOT EXISTS invoices(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNIQUE NOT NULL,amount INT UNSIGNED NOT NULL,paid INT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id));
CREATE TABLE IF NOT EXISTS payments(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,amount INT UNSIGNED NOT NULL,method ENUM('CASH','TRANSFER') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE IF NOT EXISTS knowledge(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,source VARCHAR(500) NOT NULL,approved BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
